    telemetry_url = stage_cfg.get("telemetry_url", "http://127.0.0.1:8080/api/telemetry")

    start_t = time.perf_counter()
    res = {
        "status": "DARK",
        "html_pass": False,
        "telemetry_pass": False,
        "latency_ms": 0.0,
        "detail": ""
