const INST_COUNT = 100000;
let instData = new Float32Array(INST_COUNT * 4); // x, y, scale, phase
let colorData = new Float32Array(INST_COUNT * 3); // r, g, b
const instBuf = gl.createBuffer();
const colorBuf = gl.createBuffer();

// Pre-allocate to prevent WebGL out of bounds error before fetch completes
gl.bindBuffer(gl.ARRAY_BUFFER, instBuf);
gl.bufferData(gl.ARRAY_BUFFER, INST_COUNT * 4 * 4, gl.DYNAMIC_DRAW);
gl.bindBuffer(gl.ARRAY_BUFFER, colorBuf);
gl.bufferData(gl.ARRAY_BUFFER, INST_COUNT * 3 * 4, gl.DYNAMIC_DRAW);

let astLoaded = false;
fetch('ast_nodes.json').then(r => r.json()).then(data => {
    for(let i=0; i<data.nodes.length; i++) {
        let n = data.nodes[i];
        instData[i*4+0] = n.x;
        instData[i*4+1] = n.y;
        instData[i*4+2] = n.scale;
        instData[i*4+3] = Math.random() * Math.PI * 2;
        colorData[i*3+0] = n.r;
        colorData[i*3+1] = n.g;
        colorData[i*3+2] = n.b;
    }
    gl.bindBuffer(gl.ARRAY_BUFFER, instBuf);
    gl.bufferSubData(gl.ARRAY_BUFFER, 0, instData);
    gl.bindBuffer(gl.ARRAY_BUFFER, colorBuf);
    gl.bufferSubData(gl.ARRAY_BUFFER, 0, colorData);
    astLoaded = true;
});"""

content = re.sub(r"// Load Real Codebase AST Nodes.*?\}\);", new_init, content, flags=re.DOTALL)

with open(path, 'w') as f:
    f.write(content)
